    return False

def mean_absolute_deviation(numbers: 'List[float]') -> float:
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: single cell
    if N == 1:
        return grid[1][1]

    INF_NEG = -10**9
    # dp[i1][i2] for current step t
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # Total steps from 2 to 2N
    for t in range(2, 2 * N + 1):
        newdp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range: max(1, t-N) to min(N, t-1)
        i_min = max(1, t - N)
        i_max = min(N, t - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                best = INF_NEG
                # transitions
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        if dp[pi1][pi2] > best:
                            best = dp[pi1][pi2]
                if best == INF_NEG:
                    continue
                val = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    val += grid[i2][j2]
                newdp[i1][i2] = best + val
        dp = newdp

    return dp[N][N] if dp[N][N] != INF_NEG else 0

